import{_ as e,o as d,c as r,a2 as a}from"./chunks/framework.B65tnXzx.js";const f=JSON.parse('{"title":"Glossary","description":"","frontmatter":{"title":"Glossary","titleZh":"术语表","category":"guide","outline":"deep"},"headers":[],"relativePath":"glossary.md","filePath":"glossary.md"}'),o={name:"glossary.md"};function n(i,t,s,c,l,h){return d(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="📚-glossary" tabindex="-1">📚 Glossary <a class="header-anchor" href="#📚-glossary" aria-label="Permalink to &quot;📚 Glossary&quot;">​</a></h1><blockquote><p>A bilingual glossary of terms used throughout this documentation. Terminology is kept consistent across all pages.</p></blockquote><h2 id="core-terms" tabindex="-1">Core Terms <a class="header-anchor" href="#core-terms" aria-label="Permalink to &quot;Core Terms&quot;">​</a></h2><table tabindex="0"><thead><tr><th>English</th><th>中文</th><th>Notes</th></tr></thead><tbody><tr><td>Effect</td><td>效果</td><td>The action that gets executed, e.g. dealing damage, spawning particles</td></tr><tr><td>Trigger</td><td>触发器</td><td>The event/action that causes the effect to run</td></tr><tr><td>Condition</td><td>条件</td><td>A requirement that must be met for the effect to activate</td></tr><tr><td>Mutator</td><td>变异器</td><td>Modifies the data passed to an effect before it runs</td></tr><tr><td>Filter</td><td>过滤器</td><td>Narrows down when a trigger activates by restricting targets</td></tr><tr><td>Chain</td><td>效果链</td><td>A group of effects executed together under one trigger</td></tr><tr><td>Cooldown</td><td>冷却时间</td><td>The time between effect activations</td></tr><tr><td>Chance</td><td>触发概率</td><td>The percentage chance of an effect activating</td></tr><tr><td>Target</td><td>目标</td><td>The entity the effect applies to</td></tr><tr><td>Entity</td><td>实体</td><td>A creature, player, or object in the game world</td></tr><tr><td>Victim</td><td>受害者/目标</td><td>The entity affected by an action</td></tr><tr><td>Dispatcher</td><td>派发者</td><td>The entity that triggers the effect</td></tr><tr><td>Holder</td><td>持有者</td><td>The config holding effects (enchant, talisman, reforge, etc.)</td></tr><tr><td>Placeholder</td><td>占位符</td><td>A token like <code>%level%</code> that resolves to a value</td></tr><tr><td>Multiplier</td><td>倍率/乘数</td><td>A value that multiplies another value</td></tr><tr><td>Amplifier</td><td>增幅器</td><td>A potion effect amplifier level</td></tr><tr><td>Duration</td><td>持续时间</td><td>How long an effect lasts</td></tr><tr><td>Stacking</td><td>叠加</td><td>Multiple effects of the same type combining</td></tr><tr><td>Configuration</td><td>配置</td><td>YAML settings that define behavior</td></tr><tr><td>YAML</td><td>YAML</td><td>A human-readable data serialization format (not translated)</td></tr><tr><td>Permanent Effect</td><td>永久型效果</td><td>An effect always active while conditions are met</td></tr><tr><td>Triggered Effect</td><td>触发型效果</td><td>An effect requiring a trigger to activate</td></tr></tbody></table><h2 id="argument-option-terms" tabindex="-1">Argument &amp; Option Terms <a class="header-anchor" href="#argument-option-terms" aria-label="Permalink to &quot;Argument &amp; Option Terms&quot;">​</a></h2><table tabindex="0"><thead><tr><th>English</th><th>中文</th><th>Notes</th></tr></thead><tbody><tr><td>args</td><td>参数</td><td>The arguments of an effect/condition/mutator</td></tr><tr><td>chance</td><td>触发概率</td><td>Activation chance as a percentage</td></tr><tr><td>cost</td><td>花费</td><td>Money cost to activate (Vault)</td></tr><tr><td>every</td><td>每隔</td><td>Activate every x times</td></tr><tr><td>require</td><td>要求</td><td>Require an expression to be true</td></tr><tr><td>cooldown</td><td>冷却</td><td>Cooldown in seconds</td></tr><tr><td>cooldown_group</td><td>冷却组</td><td>Shared cooldown group</td></tr><tr><td>mana_cost</td><td>法力消耗</td><td>Mana/magic cost (AuraSkills/EcoSkills)</td></tr><tr><td>delay</td><td>延迟</td><td>Delay in ticks before execution</td></tr><tr><td>repeat</td><td>重复</td><td>Repeated activation</td></tr><tr><td>price</td><td>价格</td><td>Price required to activate</td></tr><tr><td>run-order</td><td>运行顺序</td><td>Execution order: start/early/normal/late/end</td></tr><tr><td>load-weight</td><td>加载权重</td><td>Config load order weight</td></tr><tr><td>inverse</td><td>反向</td><td>Negates a condition</td></tr><tr><td>not-met-lines</td><td>未满足提示行</td><td>Lore lines when a condition is not met</td></tr><tr><td>not-met-effects</td><td>未满足效果</td><td>Effects run when a condition is not met</td></tr></tbody></table><h2 id="ecoenchants-terms" tabindex="-1">EcoEnchants Terms <a class="header-anchor" href="#ecoenchants-terms" aria-label="Permalink to &quot;EcoEnchants Terms&quot;">​</a></h2><table tabindex="0"><thead><tr><th>English</th><th>中文</th><th>Notes</th></tr></thead><tbody><tr><td>Enchantment</td><td>附魔</td><td>A custom enchantment</td></tr><tr><td>max-level</td><td>最高等级</td><td>The maximum enchantment level</td></tr><tr><td><code>%level%</code></td><td>等级占位符</td><td>Returns the enchantment level</td></tr><tr><td>Rarity</td><td>稀有度</td><td>Controls how enchantments are obtained</td></tr><tr><td>Target</td><td>目标物品</td><td>Items an enchantment can apply to</td></tr><tr><td>Conflict</td><td>冲突</td><td>Enchantments that cannot coexist</td></tr><tr><td>Spell Enchantment</td><td>法术附魔</td><td>Alt-click activated ability with cooldown</td></tr><tr><td>Special Enchantment</td><td>特殊附魔</td><td>Powerful, limited to one per item</td></tr><tr><td>Curse Enchantment</td><td>诅咒附魔</td><td>Makes the item worse</td></tr><tr><td>Artifact Enchantment</td><td>工艺品附魔</td><td>Purely cosmetic</td></tr><tr><td>cost-exponent</td><td>成本指数</td><td>Anvil cost scaling exponent</td></tr></tbody></table><h2 id="eco-core-library-terms" tabindex="-1">eco Core Library Terms <a class="header-anchor" href="#eco-core-library-terms" aria-label="Permalink to &quot;eco Core Library Terms&quot;">​</a></h2><table tabindex="0"><thead><tr><th>English</th><th>中文</th><th>Notes</th></tr></thead><tbody><tr><td>Points</td><td>点数</td><td>Numeric per-player/server/item tracking</td></tr><tr><td>Global Points</td><td>全局点数</td><td>Server-wide points</td></tr><tr><td>Item Points</td><td>物品点数</td><td>Points tied to a specific item</td></tr><tr><td>Item Levels</td><td>物品等级</td><td>XP-based item progression</td></tr><tr><td>Price System</td><td>价格系统</td><td>Unified way to handle multiple economies</td></tr><tr><td>Math Expressions</td><td>数学表达式</td><td><code>1 + 0.2 * %level%</code> style expressions</td></tr><tr><td>Custom Arguments</td><td>自定义参数</td><td>Reusable effect argument logic</td></tr><tr><td>Custom Placeholders</td><td>自定义占位符</td><td>User-defined placeholders in placeholders.yml</td></tr><tr><td>Effect Chain</td><td>效果链</td><td>Groups of effects run together</td></tr></tbody></table><h2 id="related-pages" tabindex="-1">Related Pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related Pages&quot;">​</a></h2><ul><li><a href="./guide/effect-basics">Guide: Effect Basics</a></li><li><a href="./guide/ecoenchants-specific">Guide: EcoEnchants Specific</a></li><li><a href="./effects/">All Effects</a></li></ul>',12)])])}const u=e(o,[["render",n]]);export{f as __pageData,u as default};
